#!/bin/sh
# Generated by agnostic-ai. Do not edit this file directly; edit specs under .agnostic-ai/ and run `agnostic-ai sync`.

# Blocks Gemini CLI write_file and replace edits to the protected paths in settings specs.
# Needs only a POSIX shell and awk. Exit 2 blocks the edit; stderr says why.
# Gemini CLI lets an edit through when a hook fails, so every failure exits 2.
LC_ALL=C
export LC_ALL
unset CDPATH
fail() {
  printf 'agnostic-ai: %s, so the protect hook blocked this edit.\n' "$1" >&2
  exit 2
}
command -v awk >/dev/null 2>&1 || fail "awk is not on PATH"
case $0 in
*/*) hooks_dir=${0%/*} ;;
*) hooks_dir=. ;;
esac
AGNOSTIC_AI_ROOT=$(cd -- "$hooks_dir/../.." && pwd -P) || fail "the project root is not readable"
AGNOSTIC_AI_LOGICAL_ROOT=$(cd -- "$hooks_dir/../.." && pwd -L) || fail "the project root is not readable"
AGNOSTIC_AI_CWD=$(pwd -P) || fail "the working directory is not readable"
AGNOSTIC_AI_LOGICAL_CWD=$(pwd -L) || fail "the working directory is not readable"
export AGNOSTIC_AI_ROOT AGNOSTIC_AI_LOGICAL_ROOT AGNOSTIC_AI_CWD AGNOSTIC_AI_LOGICAL_CWD
awk 'function clean(p,    n, parts, i, k, out, stack) {
  n = split(p, parts, "/")
  k = 0
  for (i = 1; i <= n; i++) {
    if (parts[i] == "" || parts[i] == ".") continue
    if (parts[i] == "..") { if (k > 0) k--; continue }
    stack[++k] = parts[i]
  }
  out = ""
  for (i = 1; i <= k; i++) out = out "/" stack[i]
  return out
}
function drive(p) {
  if (p ~ /^[A-Za-z]:\//) return "/" tolower(substr(p, 1, 1)) substr(p, 3)
  return p
}
function under(abs,    lower) {
  lower = tolower(abs)
  if (index(lower, tolower(root) "/") == 1) return substr(abs, length(root) + 2)
  if (index(lower, tolower(lroot) "/") == 1) return substr(abs, length(lroot) + 2)
  return ""
}
function relative(p,    abs, rel, i) {
  p = drive(p)
  if (substr(p, 1, 1) == "/") abs = clean(p); else abs = clean(cwd "/" p)
  rel = under(abs)
  for (i = 1; rel == "" && i <= nalias; i++) {
    if (index(tolower(abs), tolower(alias[i]) "/") == 1) rel = under(clean(cwd "/" substr(abs, length(alias[i]) + 2)))
  }
  return rel
}
function check(p,    rel, cand, i) {
  rel = relative(p)
  if (rel == "" || (rel in seen)) return
  seen[rel] = 1
  cand = tolower(rel)
  while (1) {
    for (i = 1; i <= npat; i++) {
      if (cand ~ pat[i]) {
        block(rel " is protected (" txt[i] "). " why[grp[i]])
        return
      }
    }
    if (index(cand, "/") == 0) return
    sub(/\/[^\/]*$/, "", cand)
  }
}
function block(message) {
  blocked[++nblocked] = "agnostic-ai: " message
}
function addAlias(p) {
  p = drive(p)
  if (substr(p, 1, 1) != "/") return
  p = clean(p)
  if (p != "" && p != cwd) alias[++nalias] = p
}
function restore(p, code, text,    parts, n, i, out) {
  if (index(p, code) == 0) return p
  n = split(p, parts, code)
  out = parts[1]
  for (i = 2; i <= n; i++) out = out text parts[i]
  return out
}
function unicode(h,    v, i, d) {
  v = 0
  for (i = 1; i <= 4; i++) {
    d = index("0123456789abcdef", tolower(substr(h, i, 1)))
    if (d == 0) return "\003"
    v = v * 16 + d - 1
  }
  if (v == 0) return "\003"
  if (v == 34) return "\002"
  if (v == 92) return "\001"
  if (v >= 128) return "\200"
  return sprintf("%c", v)
}
function start() {
  want["file_path"] = 1; want["cwd"] = 1; want["tool_name"] = 1
}
function text(s,    n, parts, i) {
  n = split(s, parts, "\"")
  for (i = 1; i <= n; i++) {
    if (i > 1) { if (instr) closed(); else opened() }
    if (instr) absorb(parts[i]); else between(parts[i])
  }
}
function between(t) {
  gsub(/[ \t\r\n]+/, "", t)
  if (t == "") return
  if (st == 1 && t == ":" && (key in want)) st = 2
  else st = 0
}
function opened() {
  instr = 1
  cap = ""
  toolong = 0
  value = (st == 2)
}
function absorb(t) {
  if (!value) { if (length(cap) <= 16) cap = cap substr(t, 1, 17); return }
  if (length(cap) + length(t) > 4096) toolong = 1
  else cap = cap t
}
function closed() {
  instr = 0
  if (!value) { key = cap; st = 1; return }
  st = 0
  store(key, cap)
}
function store(k, v,    s) {
  if (toolong) { block("the " k " is longer than the 4096 bytes the hook checks. Use a shorter path."); return }
  v = restore(restore(v, "\002", "\""), "\001", "/")
  if (k == "cwd") { if (!havecwd) { havecwd = 1; addAlias(v) } return }
  if (k == "tool_name") { if (!havetool) { havetool = 1; tool = v } return }
  v = restore(v, "\003", "")
  if (v == "") return
  named[++nnamed] = v
  paths[++npaths] = v
  s = unprefixed(v)
  if (s == "") return
  paths[++npaths] = s
  if (v ~ /^@\//) paths[++npaths] = substr(v, 2)
}
function unprefixed(p) {
  if (p !~ /^@./) return ""
  p = substr(p, 2)
  sub(/^\/+/, "", p)
  return p
}
function exists(p,    r, l) {
  r = (getline l < p)
  close(p)
  return r >= 0
}
function finish(    i, p, s) {
  if (tool != "replace") return
  for (i = 1; i <= nnamed; i++) {
    p = drive(named[i])
    if (substr(p, 1, 1) == "/" || exists(p)) continue
    s = unprefixed(p)
    if (s != "" && exists(s)) continue
    block(p " does not exist from the project root, so Gemini CLI would search the workspace for a file that ends with it, and the hook cannot check which one. Give the path from the project root.")
  }
}
BEGIN {
  RS = "\\"
  esc["\""] = "\002"; esc["/"] = "/"; esc["t"] = "\t"; esc["r"] = "\r"; esc["f"] = "\f"; esc["b"] = "\b"; esc["n"] = "\n"
  root = drive(ENVIRON["AGNOSTIC_AI_ROOT"])
  lroot = drive(ENVIRON["AGNOSTIC_AI_LOGICAL_ROOT"])
  cwd = drive(ENVIRON["AGNOSTIC_AI_CWD"])
  addAlias(ENVIRON["AGNOSTIC_AI_LOGICAL_CWD"])
  why[1] = "CI and the lock file change only on purpose. Ask the user before editing it. This hook blocks the edit either way, so the user makes the change or removes the path from the protected list."
  pat[1] = "^\\.github/.+$"; txt[1] = ".github/**"; grp[1] = 1
  pat[2] = "^composer\\.lock$"; txt[2] = "composer.lock"; grp[2] = 1
  npat = 2
  start()
}
NR == 1 { text($0); next }
plain { plain = 0; text($0); next }
$0 == "" { text("\001"); plain = 1; next }
{
  c = substr($0, 1, 1)
  r = substr($0, 2)
  if (c == "u") text(unicode(substr(r, 1, 4)) substr(r, 5))
  else if (c in esc) text(esc[c] r)
  else text(c r)
}
END {
  finish()
  for (i = 1; i <= npaths; i++) check(paths[i])
  for (i = 1; i <= nblocked; i++) print blocked[i]
  if (nblocked > 0) exit 2
}
' 1>&2
status=$?
case $status in
0) exit 0 ;;
2) exit 2 ;;
esac
fail "awk stopped with status $status"
